package com.oldschoolnetwork.store.lite;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import com.oldschoolnetwork.lite.*;
import org.json.*;
import java.util.*;

public final class DetailsActivity extends Activity {
 private JSONObject app,release,myReview;private JSONArray reviews=new JSONArray();private int id,rating;private TextView status;private final Handler ui=new Handler();private boolean listening;
 private final BroadcastReceiver transfer=new BroadcastReceiver(){public void onReceive(Context c,Intent i){renderTransfer();}};
 public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.details);id=getIntent().getIntExtra("app_id",0);status=(TextView)findViewById(R.id.status);
  findViewById(R.id.back).setOnClickListener(new View.OnClickListener(){public void onClick(View v){finish();}});
  findViewById(R.id.download).setOnClickListener(new View.OnClickListener(){public void onClick(View v){download();}});
  findViewById(R.id.open).setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(app==null)return;Intent launch=getPackageManager().getLaunchIntentForPackage(app.optString("package_name"));if(launch!=null)startActivity(launch);}});
  findViewById(R.id.cancel).setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(app!=null)getSharedPreferences("transfers",0).edit().putBoolean(app.optString("package_name")+".cancel",true).commit();}});
  findViewById(R.id.versions).setOnClickListener(new View.OnClickListener(){public void onClick(View v){versions();}});
  findViewById(R.id.favorite).setOnClickListener(new View.OnClickListener(){public void onClick(View v){favorite();}});
  findViewById(R.id.report).setOnClickListener(new View.OnClickListener(){public void onClick(View v){ReportDialog.show(DetailsActivity.this,"app",id);}});
  findViewById(R.id.share).setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"https://oldschoolnetwork.online/store/?app_id="+id),"Share application"));}});
  findViewById(R.id.more_description).setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(app==null)return;TextView text=(TextView)getLayoutInflater().inflate(R.layout.description,null);text.setText(app.optString("description"));ScrollView scroll=(ScrollView)getLayoutInflater().inflate(R.layout.description_scroll,null);scroll.addView(text);new AlertDialog.Builder(DetailsActivity.this).setTitle(app.optString("name")).setView(scroll).setPositiveButton("Close",null).show();}});
  findViewById(R.id.submit_review).setOnClickListener(new View.OnClickListener(){public void onClick(View v){submitReview();}});
  findViewById(R.id.edit_review).setOnClickListener(new View.OnClickListener(){public void onClick(View v){findViewById(R.id.composer).setVisibility(View.VISIBLE);findViewById(R.id.edit_review).setVisibility(View.GONE);}});
  for(int i=1;i<=5;i++){final int value=i;findViewById(starId(i)).setOnClickListener(new View.OnClickListener(){public void onClick(View v){rating=value;stars();}});}
  load();
 }
 private int starId(int n){return getResources().getIdentifier("star"+n,"id",getPackageName());}
 private void stars(){for(int i=1;i<=5;i++)((ImageView)findViewById(starId(i))).setImageResource(i<=rating?R.drawable.star_selected:R.drawable.star_unselected);}
 private JSONObject target(){JSONObject b=new JSONObject();try{b.put("app_id",id);}catch(Exception ignored){}return b;}
 private void load(){status.setText("Loading…");Api.call(this,"store_app_details",target(),Api.account(this)!=null,new Api.Callback(){public void complete(JSONObject r,String error){if(isFinishing())return;if(error!=null){status.setText(error);return;}app=r.optJSONObject("app");if(app==null){status.setText("This application is no longer available.");return;}myReview=r.optJSONObject("my_review");reviews=r.optJSONArray("reviews")==null?new JSONArray():r.optJSONArray("reviews");release=Transfers.newest(app);render();}});}
 private void render(){
  ((TextView)findViewById(R.id.title)).setText(app.optString("name"));((TextView)findViewById(R.id.developer)).setText("own".equals(app.optString("app_mode"))?app.optString("publisher_studio"):app.optString("original_dev"));Images.load(this,(ImageView)findViewById(R.id.icon),app.optString("icon_url"),144);
  String text=app.optString("description");int end=text.offsetByCodePoints(0,Math.min(300,text.codePointCount(0,text.length())));((TextView)findViewById(R.id.description)).setText(text.substring(0,end));findViewById(R.id.more_description).setVisibility(end<text.length()?View.VISIBLE:View.GONE);
  ((TextView)findViewById(R.id.rating)).setText(app.optString("rating_avg","—")+" · "+app.optInt("downloads")+" downloads");
  ((TextView)findViewById(R.id.guardy)).setText("ON Guardy · "+app.optString("guardy_rating","UR")+"+ · Learn more");findViewById(R.id.guardy).setOnClickListener(new View.OnClickListener(){public void onClick(View v){new AlertDialog.Builder(DetailsActivity.this).setTitle("ON Guardy").setMessage("ON Guardy is Oldschool Network's age classification. It describes the recommended audience and content warnings, not an antivirus result.\n\n"+app.optJSONArray("guardy_reasons")).setPositiveButton("Close",null).show();}});
  ((Button)findViewById(R.id.favorite)).setText(app.optBoolean("is_favorite")?"In favorites":"Favorite");findViewById(R.id.favorite).setSelected(app.optBoolean("is_favorite"));
  LinearLayout shots=(LinearLayout)findViewById(R.id.screenshots);shots.removeAllViews();JSONArray photos=app.optJSONArray("screenshots");if(photos!=null)for(int i=0;i<photos.length()&&i<8;i++){final String url=photos.optString(i);ImageView image=(ImageView)getLayoutInflater().inflate(R.layout.screenshot,shots,false);shots.addView(image);Images.load(this,image,url,480);image.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(DetailsActivity.this,MediaActivity.class).putExtra("url",url));}});}
  JSONArray videos=app.optJSONArray("videos");findViewById(R.id.video).setVisibility(videos!=null&&videos.length()>0?View.VISIBLE:View.GONE);if(videos!=null&&videos.length()>0){final String url=videos.optString(0);findViewById(R.id.video).setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(url),"video/*"));}catch(Exception e){status.setText("No compatible video player is installed.");}}});}
  status.setText("");renderTransfer();renderReviews();permissions();rating=myReview==null?0:myReview.optInt("rating");stars();((EditText)findViewById(R.id.review_text)).setText(myReview==null?"":myReview.optString("review_text"));findViewById(R.id.composer).setVisibility(myReview==null?View.VISIBLE:View.GONE);findViewById(R.id.edit_review).setVisibility(myReview==null?View.GONE:View.VISIBLE);
 }
 private void permissions(){if(release==null)return;final LinkedHashMap<String,LinkedHashSet<String>> groups=new LinkedHashMap<String,LinkedHashSet<String>>();JSONArray list=release.optJSONArray("permissions_list");if(list==null)list=app.optJSONArray("permissions_list");if(list!=null)for(int i=0;i<list.length();i++){String exact=list.optString(i),name=PermissionCatalog.describe(exact).title;if(!groups.containsKey(name))groups.put(name,new LinkedHashSet<String>());groups.get(name).add(exact);}final ArrayList<String> keys=new ArrayList<String>(groups.keySet());findViewById(R.id.permissions).setOnClickListener(new View.OnClickListener(){public void onClick(View v){new AlertDialog.Builder(DetailsActivity.this).setTitle("Required permissions").setItems(keys.toArray(new String[keys.size()]),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){StringBuilder exact=new StringBuilder();for(String s:groups.get(keys.get(n)))exact.append(s).append('\n');new AlertDialog.Builder(DetailsActivity.this).setTitle(keys.get(n)).setMessage(exact.toString()).setPositiveButton("Close",null).show();}}).setPositiveButton("Close",null).show();}});}
 private void versions(){if(app==null)return;final ArrayList<JSONObject> options=new ArrayList<JSONObject>();JSONArray all=app.optJSONArray("packages");if(all!=null)for(int i=0;i<all.length();i++)if(Transfers.compatible(all.optJSONObject(i)))options.add(all.optJSONObject(i));String[] names=new String[options.size()];for(int i=0;i<names.length;i++)names[i]=options.get(i).optString("version_name")+" · "+options.get(i).optString("size_label");new AlertDialog.Builder(this).setTitle("Compatible APK versions").setItems(names,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){release=options.get(n);permissions();renderTransfer();}}).setNegativeButton("Close",null).show();}
 private void renderTransfer(){if(app==null)return;String name=app.optString("package_name"),phase=Transfers.phase(this,name);int installed=Transfers.installed(this,name);Button button=(Button)findViewById(R.id.download);findViewById(R.id.open).setVisibility(installed>=0?View.VISIBLE:View.GONE);boolean downloading="downloading".equals(phase),installing="installing".equals(phase);findViewById(R.id.cancel).setVisibility(downloading?View.VISIBLE:View.GONE);ProgressBar bar=(ProgressBar)findViewById(R.id.progress);bar.setVisibility(downloading||installing?View.VISIBLE:View.GONE);bar.setIndeterminate(installing);bar.setProgress(getSharedPreferences("transfers",0).getInt(name+".progress",0));
  button.setEnabled(release!=null&&!downloading&&!installing);button.setText(installing?"Installing…":downloading?"Downloading…":"ready".equals(phase)?"Install APK":installed>=0&&release!=null&&release.optInt("version_code")>installed?"Update":"Download");if(release==null)button.setText("No compatible APK");if(installed>=0&&release!=null&&release.optInt("version_code")<=installed&&!"ready".equals(phase))button.setVisibility(View.GONE);else button.setVisibility(View.VISIBLE);
  if("ready".equals(phase)||"error".equals(phase))status.setText(getSharedPreferences("transfers",0).getString(name+".message",""));
 }
 private void download(){if(app==null||release==null)return;final String name=app.optString("package_name");if("ready".equals(Transfers.phase(this,name))){try{Transfers.install(this,name);}catch(Exception e){status.setText("Android's package installer is unavailable.");}return;}
  if(app.optDouble("price_amount",0)>0&&!app.optBoolean("is_owned")){status.setText("Acquire this application with your account before downloading.");return;}
  if(Api.account(this)!=null){JSONObject b=target();Api.call(this,"store_acquire_app",b,true,new Api.Callback(){public void complete(JSONObject r,String error){if(error!=null){status.setText(error);return;}startDownload();}});}else startDownload();
 }
 private void startDownload(){startService(new Intent(this,Transfers.class).putExtra("app_id",id).putExtra("package",app.optString("package_name")).putExtra("release",release.toString()));ui.postDelayed(new Runnable(){public void run(){if(!isFinishing())renderTransfer();}},300);}
 private void favorite(){if(app==null)return;JSONObject b=target();try{b.put("favorite",!app.optBoolean("is_favorite"));}catch(Exception ignored){}Api.call(this,"store_set_favorite",b,true,new Api.Callback(){public void complete(JSONObject r,String error){if(error!=null)status.setText(error);else load();}});}
 private void submitReview(){if(rating==0){status.setText("Select at least one star before publishing.");return;}JSONObject b=target();try{b.put("rating",rating).put("review_text",((EditText)findViewById(R.id.review_text)).getText().toString());}catch(Exception ignored){}Api.call(this,"store_submit_review",b,true,new Api.Callback(){public void complete(JSONObject r,String error){if(error!=null)status.setText(error);else load();}});}
 private void renderReviews(){LinearLayout list=(LinearLayout)findViewById(R.id.reviews);list.removeAllViews();for(int i=0;i<reviews.length()&&i<30;i++){final JSONObject review=reviews.optJSONObject(i);View row=getLayoutInflater().inflate(R.layout.review,list,false);list.addView(row);((TextView)row.findViewById(R.id.author)).setText("@"+review.optString("username"));Images.load(this,(ImageView)row.findViewById(R.id.avatar),review.optString("avatar_base64").startsWith("data:")?review.optString("avatar_base64"):"data:image/png;base64,"+review.optString("avatar_base64"),96);((TextView)row.findViewById(R.id.text)).setText(review.optString("review_text"));((TextView)row.findViewById(R.id.date)).setText(review.optString("updated_at"));for(int n=1;n<=5;n++)((ImageView)row.findViewById(starId(n))).setImageResource(n<=review.optInt("rating")?R.drawable.star_selected:R.drawable.star_unselected);
   TextView reply=(TextView)row.findViewById(R.id.reply);String replyText=review.isNull("reply_text")?"":review.optString("reply_text");reply.setText(replyText);reply.setVisibility(replyText.length()>0?View.VISIBLE:View.GONE);if("maintainer".equals(review.optString("reply_role")))reply.setTextColor(0xFFBD6C00);
   reaction(row,R.id.like,review,1);reaction(row,R.id.dislike,review,-1);row.findViewById(R.id.report_review).setOnClickListener(new View.OnClickListener(){public void onClick(View v){ReportDialog.show(DetailsActivity.this,"review",review.optInt("id"));}});
  }}
 private void reaction(View row,int buttonId,final JSONObject review,final int value){final Button button=(Button)row.findViewById(buttonId);button.setText((value==1?"Like ":"Dislike ")+review.optInt(value==1?"likes":"dislikes"));button.setTextColor(review.optInt("my_reaction")==value?0xFF008FA8:0xFF444444);button.setOnClickListener(new View.OnClickListener(){public void onClick(View v){JSONObject b=new JSONObject();try{b.put("review_id",review.optInt("id")).put("reaction",review.optInt("my_reaction")==value?0:value);}catch(Exception ignored){}Api.call(DetailsActivity.this,"store_review_react",b,true,new Api.Callback(){public void complete(JSONObject r,String error){if(error!=null)status.setText(error);else load();}});}});}
 protected void onResume(){super.onResume();registerReceiver(transfer,new IntentFilter(getPackageName()+".TRANSFER"));listening=true;renderTransfer();}
 protected void onPause(){if(listening){unregisterReceiver(transfer);listening=false;}super.onPause();}
}
